// Types from @microsoft/rayfin-connectors 2.0.0 (MIT, Microsoft Corporation), copied from
// dist/connectorsService.d.ts, dist/ConnectorsSchema.d.ts, dist/Connectors.d.ts,
// dist/contracts.d.ts and dist/category-a/ (schema/source.d.ts, types.d.ts,
// ConnectorEntityClient.d.ts, ConnectorGraphQLQueryBuilder.d.ts) with comments shortened.
// A subset: what a semantic model connector and a read-only entity connector use.
// Simplified for entities: selections of scalar fields only (the dotted relationship paths,
// runtime-built field lists, AutoGenerated columns, groupBy and aggregate are left out), and one
// row builder type before and after select().
declare module '@microsoft/rayfin-connectors' {
  import type { ClientServiceFactory } from '@microsoft/rayfin-lib';
  import { RayfinPrimaryKey, type EntityClass } from '@microsoft/rayfin-core';
  import type { FilterInput, GraphQLResponseValue, OrderByInput, PagedResult, ProjectionScalar } from '@microsoft/rayfin-data';

  export type ConnectorType =
    | 'fabric-sqlanalytics'
    | 'fabric-warehouse'
    | 'fabric-sqldatabase'
    | 'fabric-semanticmodel'
    | 'fabriciqmcp'
    | 'eventhouse'
    | 'fabric-dataagent'
    | 'office365users'
    | 'sharepointonline'
    | 'office365'
    | 'excelonlinebusiness'
    | 'teams'
    | 'onedriveforbusiness'
    | 'office365groups'
    | 'microsoftforms'
    | 'planner'
    | 'azuread';

  /** Per-operation input/output binding (type level only). */
  export interface OperationDef<TInput = unknown, TOutput = unknown> {
    readonly __input?: TInput;
    readonly __output?: TOutput;
  }

  export type OperationCatalog = Record<string, OperationDef<unknown, unknown>>;

  /** Type marker for a connector: pins its client shape and its accepted configuration. */
  export interface ConnectorMarker<TClient = unknown, TConfig extends ConnectorConfig = ConnectorConfig> {
    readonly __client?: TClient;
    readonly __config?: TConfig;
  }

  /** Maps connector instance names (as declared in `rayfin.yml`) to their markers. */
  export type ConnectorsSchema = Record<string, ConnectorMarker>;

  /** Configuration for every connector in a schema, checked against each marker's config type. */
  export type ConnectorConfigs<TSchema extends ConnectorsSchema> = {
    [K in keyof TSchema & string]: TSchema[K] extends ConnectorMarker<unknown, infer TConfig> ? TConfig : never;
  };

  /** Options for a single connector operation call. */
  export interface InvokeOptions {
    headers?: Record<string, string>;
    /** Per-call timeout in milliseconds; capped at the 5-minute default. */
    timeoutMs?: number;
  }

  export type ConnectorConnectionState = 'Connected' | 'ConsentRequired' | 'Provisioning' | 'NotRequired';

  export interface ConnectorConnectionStatus {
    connector: string;
    status: ConnectorConnectionState;
    consentUrl?: string;
    retryAfterSeconds?: number;
  }

  export interface ConnectorConnection {
    status(): Promise<ConnectorConnectionStatus>;
    connect(options?: { mode?: 'popup' | 'redirect'; pollIntervalMs?: number; timeoutMs?: number; signal?: AbortSignal }): Promise<ConnectorConnectionStatus>;
  }

  /** The typed `client.connectors.<name>` entry for an operation-catalog connector. */
  export type TypedConnectorClient<TCatalog extends OperationCatalog> = {
    [K in Exclude<keyof TCatalog & string, 'connection'>]: TCatalog[K] extends OperationDef<infer TIn, infer TOut>
      ? unknown extends TIn
        ? (input?: TIn, options?: InvokeOptions) => Promise<TOut>
        : (input: TIn, options?: InvokeOptions) => Promise<TOut>
      : never;
  } & {
    readonly connection: ConnectorConnection;
  };

  /** Operations of the entity (SQL) connectors. */
  export type CrudOperation = 'read' | 'create' | 'update' | 'delete';

  /** The entity-client methods each CRUD operation allows. */
  export const METHODS_FOR_CRUD_OPERATION: {
    readonly read: readonly ['select', 'where', 'orderBy', 'first', 'groupBy', 'aggregate', 'findMany', 'findFirst', 'findByKey'];
    readonly create: readonly ['create'];
    readonly update: readonly ['update'];
    readonly delete: readonly ['delete'];
  };

  /** Runtime config passed per connector, mirrored from its generated `schema.ts`. */
  export interface ConnectorConfig {
    /** Connector type from `rayfin.yml`. */
    connector: ConnectorType;
    /**
     * Optional CRUD allow-list (entity connectors only). A method whose operation is not in
     * this list throws `ConnectorsError` with code `OPERATION_NOT_ALLOWED`.
     */
    operations?: readonly CrudOperation[];
    /**
     * Per-entity metadata keyed by entity name: the decorated entity class or a list of its
     * field names. Supplies the default selection of reads without `select`.
     */
    entities?: Record<string, EntityClass | readonly string[]>;
  }

  export interface OperationRuntime {}

  /** Runtime hooks for one connector, supplied by its connector package. */
  export interface ConnectorRuntime {
    operations?: Record<string, OperationRuntime>;
  }

  export type ConnectorsRuntime = Record<string, ConnectorRuntime>;

  export interface HostEnvironment {
    type: 'embedded' | 'standalone' | 'cli';
  }

  /** `client.connectors`: one typed client per schema entry. */
  export type TypedConnectorsApi<TSchema extends ConnectorsSchema> = {
    [K in keyof TSchema & string]: TSchema[K] extends ConnectorMarker<infer C> ? C : never;
  };

  export interface ConnectorsServiceOptions<TSchema extends ConnectorsSchema> {
    /** Configuration matching every connector's type in the declared schema. */
    configs: ConnectorConfigs<TSchema>;
    /** Operation middleware and decoders. Semantic model connectors need theirs here. */
    runtime?: ConnectorsRuntime;
    /** Execution environment; defaults to standalone in browsers. */
    host?: HostEnvironment;
  }

  /** Register typed connectors on a composed Rayfin client. */
  export function connectorsService<TSchema extends ConnectorsSchema>(
    options: ConnectorsServiceOptions<TSchema>,
  ): ClientServiceFactory<TypedConnectorsApi<TSchema>>;

  // ------------------------------------------------------------ entity connectors (Category A)
  /** Carries the ordered primary-key tuple on an entity class's static type (type only). */
  export interface RayfinPrimaryKeyCarrier<PK extends readonly string[]> {
    readonly [RayfinPrimaryKey]: PK;
  }

  /** Options for `Source()`. */
  export interface SourceOptions<PK extends readonly string[] = readonly string[]> {
    /** The SQL schema. Defaults to `'dbo'`. */
    schema?: string;
    /** The SQL table name. Defaults to the decorated class name. */
    table?: string;
    /**
     * The ordered property names that form the primary key. Omit or pass `[]` for a keyless
     * entity: its by-key methods (`findByKey`, `update`, `delete`) are stripped.
     */
    primaryKey?: PK;
  }

  /** Creates the base class of a connector entity: its SQL schema, table and primary key. */
  export function Source<const PK extends readonly string[] = readonly []>(
    options?: SourceOptions<PK>,
  ): (new (...args: unknown[]) => object) & RayfinPrimaryKeyCarrier<PK>;

  /** Result returned by a connector without read-after-write (Fabric Warehouse), in place of the row. */
  export interface DbOperationResult {
    readonly result: string;
  }

  /** Instance (record) type of a schema entry, whether it is a constructor or a bare instance type. */
  export type InstanceOf<T> = T extends abstract new (...args: infer _Args) => infer I ? I : T;
  /** The row type reads, filters and ordering speak in. */
  export type Row<T> = InstanceOf<T>;

  /** Ordered primary-key tuple from the entity's static phantom; empty (keyless) when absent. */
  export type PrimaryKeyOf<T> = T extends { readonly [RayfinPrimaryKey]: infer PK }
    ? PK extends readonly string[]
      ? PK
      : readonly []
    : readonly [];

  /** By-key `where` shape: the declared key columns. A keyless entity resolves to `never`. */
  export type WhereUniqueOf<T> = PrimaryKeyOf<T> extends readonly []
    ? never
    : Pick<InstanceOf<T>, Extract<PrimaryKeyOf<T>[number], keyof InstanceOf<T>>>;

  /** Scalar (selectable) column names of `T`. */
  export type ScalarLeafKeys<T> = {
    [K in keyof T & string]: NonNullable<T[K]> extends ProjectionScalar ? K : never;
  }[keyof T & string];
  export type ScalarColumnsOf<I> = ScalarLeafKeys<I>;

  /** Selectable field set for a read: every element must be a scalar column of `T`. */
  export type ConnectorFieldSelection<T, F extends readonly string[]> = {
    readonly [I in keyof F]: ScalarLeafKeys<T>;
  };

  /** Result row of an explicit selection: exactly the selected fields, with their declared types. */
  export type ConnectorSelectionResult<T, TFields extends readonly string[]> = {
    [K in keyof T as K extends TFields[number] ? K : never]: GraphQLResponseValue<T[K]>;
  };

  /** Row returned by reads without a selection: every scalar column, each optional. */
  export type ConnectorDefaultReadResult<T> = GraphQLResponseValue<Partial<Pick<T, ScalarLeafKeys<T>>>>;

  /** What create / update / delete return: `DbOperationResult` on a Warehouse, otherwise the row. */
  export type MutationResult<TDialect extends ConnectorType, TRecord> = TDialect extends 'fabric-warehouse'
    ? DbOperationResult
    : ConnectorDefaultReadResult<TRecord>;

  /** Column values accepted when creating a row. */
  export type CreateInput<TRecord> = { [K in ScalarLeafKeys<TRecord>]: TRecord[K] };
  /** Column values accepted when updating a row: any subset of its columns. */
  export type UpdateInput<TRecord> = { [K in ScalarLeafKeys<TRecord>]?: TRecord[K] };

  /**
   * The fluent read: `select`, then `where`, `orderBy`, `first`, `after`, then `execute()` (one
   * page: 100 rows unless `first` says otherwise) or `executePaginated()` (a page and its cursor).
   */
  export interface ConnectorRowQueryBuilder<TRow, TResult> {
    select<const TFields extends readonly string[]>(
      fields: TFields & ConnectorFieldSelection<TRow, TFields>,
    ): ConnectorRowQueryBuilder<TRow, ConnectorSelectionResult<TRow, TFields>>;
    where(conditions: FilterInput<TRow>): ConnectorRowQueryBuilder<TRow, TResult>;
    orderBy(order: OrderByInput<TRow>): ConnectorRowQueryBuilder<TRow, TResult>;
    first(count: number): ConnectorRowQueryBuilder<TRow, TResult>;
    after(cursor: string): ConnectorRowQueryBuilder<TRow, TResult>;
    /** One page of matching rows (100 by default), with no signal that more exist. */
    execute(): Promise<TResult[]>;
    /** One page of matching rows, with `hasNextPage` and the `endCursor` to pass to `after()`. */
    executePaginated(): Promise<PagedResult<TResult>>;
    findFirst(): Promise<TResult | null>;
  }

  /**
   * The client for one connector entity, `client.connectors.<name>.<Entity>`. The marker in
   * `@microsoft/rayfin-connector-fabric-graphql` keeps only the methods the connector's
   * operations allow, and drops the by-key methods of a keyless entity.
   */
  export class ConnectorEntityClient<TSchema extends Record<string, unknown>, TEntity extends keyof TSchema, TDialect extends ConnectorType = ConnectorType> {
    private constructor();
    select<const TFields extends readonly string[]>(
      fields: TFields & ConnectorFieldSelection<Row<TSchema[TEntity]>, TFields>,
    ): ConnectorRowQueryBuilder<Row<TSchema[TEntity]>, ConnectorSelectionResult<Row<TSchema[TEntity]>, TFields>>;
    where(conditions: FilterInput<Row<TSchema[TEntity]>>): ConnectorRowQueryBuilder<Row<TSchema[TEntity]>, GraphQLResponseValue<Row<TSchema[TEntity]>>>;
    orderBy(order: OrderByInput<Row<TSchema[TEntity]>>): ConnectorRowQueryBuilder<Row<TSchema[TEntity]>, GraphQLResponseValue<Row<TSchema[TEntity]>>>;
    first(count: number): ConnectorRowQueryBuilder<Row<TSchema[TEntity]>, GraphQLResponseValue<Row<TSchema[TEntity]>>>;
    /** All matching rows of the registered columns, or `findMany(fields, filter?)` for chosen ones. */
    findMany(filter?: FilterInput<Row<TSchema[TEntity]>>): Promise<ConnectorDefaultReadResult<Row<TSchema[TEntity]>>[]>;
    findMany<const TFields extends readonly string[]>(
      fields: TFields & ConnectorFieldSelection<Row<TSchema[TEntity]>, TFields>,
      filter?: FilterInput<Row<TSchema[TEntity]>>,
    ): Promise<ConnectorSelectionResult<Row<TSchema[TEntity]>, TFields>[]>;
    findFirst(filter?: FilterInput<Row<TSchema[TEntity]>>): Promise<ConnectorDefaultReadResult<Row<TSchema[TEntity]>> | null>;
    findFirst<const TFields extends readonly string[]>(
      fields: TFields & ConnectorFieldSelection<Row<TSchema[TEntity]>, TFields>,
      filter?: FilterInput<Row<TSchema[TEntity]>>,
    ): Promise<ConnectorSelectionResult<Row<TSchema[TEntity]>, TFields> | null>;
    /** One row by its primary key, or `null`. */
    findByKey(where: WhereUniqueOf<TSchema[TEntity]>): Promise<ConnectorDefaultReadResult<Row<TSchema[TEntity]>> | null>;
    create(input: CreateInput<InstanceOf<TSchema[TEntity]>>): Promise<MutationResult<TDialect, Row<TSchema[TEntity]>>>;
    update(where: WhereUniqueOf<TSchema[TEntity]>, data: UpdateInput<InstanceOf<TSchema[TEntity]>>): Promise<MutationResult<TDialect, Row<TSchema[TEntity]>>>;
    delete(where: WhereUniqueOf<TSchema[TEntity]>): Promise<MutationResult<TDialect, Row<TSchema[TEntity]>>>;
  }
}
